(()=>{const viewer=document.getElementById('image-viewer');if(!viewer)return;const items=[...document.querySelectorAll('[data-gallery]')],image=viewer.querySelector('#viewer-image'),count=viewer.querySelector('#viewer-count');let current=0,opener;function show(index){current=(index+items.length)%items.length;const source=items[current].querySelector('img');image.src=source.src;image.alt=source.alt;count.textContent=`${current+1} / ${items.length}`;}items.forEach((item,index)=>item.addEventListener('click',()=>{opener=item;show(index);viewer.showModal()}));function close(){viewer.close();opener?.focus()}viewer.querySelector('.viewer-close').addEventListener('click',close);viewer.querySelector('#viewer-prev').addEventListener('click',()=>show(current-1));viewer.querySelector('#viewer-next').addEventListener('click',()=>show(current+1));viewer.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();show(current-1)}if(e.key==='ArrowRight'){e.preventDefault();show(current+1)}});viewer.addEventListener('click',e=>{if(e.target===viewer){const r=viewer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});})();
